import DetailDrawer from '../../components/DetailDrawer';
function bikes(value) { return value === null || value === undefined ? '재고 확인 필요' : `${value}대`; } function probability(value) { return value === null || value === undefined ? '판단 정보 부족' : `${Math.round(value * 100)}%`; }
export default function RiskStationDrawer({ stationNumber, detail, error, loading, onClose }) { const riskStation = detail?.station; const station = riskStation?.station; const title = station?.name || '대여소 상세'; return <DetailDrawer open={Boolean(stationNumber)} title={title} onClose={onClose} variant="contextual">{loading ? <p>불러오는 중</p> : null}{error ? <p>{error.code === 'RISK_SNAPSHOT_EXPIRED' ? '분석 결과가 만료되었습니다. 지도에서 현재 범위를 다시 분석해 주세요.' : error.status === 404 ? '대여소 상세를 찾을 수 없음' : error.status === 403 ? '접근 권한 없음' : '오류가 발생했습니다.'}<br />{error.code}</p> : null}{station ? <dl className="risk-drawer-data"><dt>대여소 번호</dt><dd>{station.stationNumber}</dd><dt>현재 자전거 수</dt><dd>{bikes(station.currentBikes)}</dd><dt>데이터 상태</dt><dd>{riskStation.dataState}</dd><dt>위험 단계</dt><dd>{riskStation.riskBand || '판단 정보 부족'}</dd><dt>선택 부족 확률</dt><dd>{probability(riskStation.rentalRisk?.selectedShortageProbability)}</dd><dt>예측 시각</dt><dd><time dateTime={riskStation.predictionTargetAt}>{riskStation.predictionTargetAt}</time></dd><dt>상세 기준</dt><dd>{detail.referenceTime}</dd>{[1, 2, 3, 4, 5].map((count) => <div key={count}><dt>{count}대 이상 확률</dt><dd>{probability(riskStation.rentalRisk?.[`atLeast${count}Probability`])} / 부족 {probability(riskStation.rentalRisk?.[`shortage${count}Probability`])}</dd></div>)}</dl> : null}</DetailDrawer>; }
