import { useEffect, useMemo, useState } from 'react';
import AsyncStatePanel from '../../components/AsyncStatePanel';
import DataExportPanel from '../exports/DataExportPanel';

const LABELS = { NORMAL: '정상', DELAYED: '지연', MISSING: '결측', PARTIAL: '운영 중 · 일부 데이터 제외', UNAVAILABLE: '사용 불가', INSUFFICIENT_DATA: '판단 정보 부족' };
const time = (value) => value ? new Date(value).toLocaleString('ko-KR') : '확인 정보 없음';
const count = (value) => typeof value === 'number' ? value.toLocaleString('ko-KR') : '확인 정보 없음';
const ratio = (value) => typeof value === 'number' ? `${(value * 100).toFixed(1)}%` : '확인 정보 없음';
function State({ value }) { return <mark className={`operations-data-state operations-data-state--${String(value || 'unknown').toLowerCase()}`}>{LABELS[value] || '확인 정보 없음'}</mark>; }
function Metric({ label, value }) { return <div className="operations-data-metric"><dt>{label}</dt><dd>{value}</dd></div>; }
function Section({ title, description, state, children }) { return <details className="operations-data-section"><summary className="operations-data-section-heading"><div><h2>{title}</h2><p>{description}</p></div><State value={state} /></summary><div className="operations-data-section-body">{children}</div></details>; }

export default function DataStatusPage({ createAdapter }) {
  const adapter = useMemo(() => createAdapter(), [createAdapter]); const [result, setResult] = useState(null); const [error, setError] = useState(null);
  useEffect(() => { const controller = new AbortController(); setResult(null); setError(null); adapter.load({ signal: controller.signal }).then(setResult).catch((next) => { if (next?.name !== 'AbortError') setError(next); }); return () => controller.abort(); }, [adapter]);
  if (error) return <AsyncStatePanel state={error.status === 401 || error.status === 403 ? 'FORBIDDEN' : 'ERROR'} code={error.code} requiredPermission="DATA_STATUS_READ" />;
  if (!result) return <AsyncStatePanel state="LOADING" />;
  const inventory = result.inventory || {}; const profile = result.profile || {}; const global = result.globalRisk || {}; const map = result.runtimeAnalysis || {};
  const inventoryBreakdown = inventory.inventoryStatusBreakdown || {};
  return <main className="operations-data-page" aria-label="데이터 상태"><header className="operations-data-header"><div><p className="operations-data-eyebrow">UI-DATA-01 · DATA_STATUS_READ</p><h1>데이터 상태</h1><p>현재 서비스가 사용하는 데이터와 운영 위험 근거를 지금 믿을 수 있는지 확인합니다.</p></div><dl><Metric label="데이터 종합 상태" value={<State value={result.dataState} />} /><Metric label="기준 시각" value={time(result.referenceTime)} /><Metric label="생성 시각" value={time(result.generatedAt)} /></dl></header>
    <Section title="현재 재고" description="활성 대여소와 최신 서비스 재고의 범위·지연입니다." state={inventory.dataState}><dl className="operations-data-metrics"><Metric label="활성 대여소" value={count(inventory.expectedStationCount)} /><Metric label="최신 재고" value={count(inventory.latestStationCount)} /><Metric label="행 없음" value={count(inventory.missingStationCount)} /><Metric label="최신 수집" value={time(inventory.latestCollectedAt)} /><Metric label="P50 지연" value={inventory.p50DelayMinutes == null ? '확인 정보 없음' : `${inventory.p50DelayMinutes}분`} /><Metric label="P95 지연" value={inventory.p95DelayMinutes == null ? '확인 정보 없음' : `${inventory.p95DelayMinutes}분`} />{['NORMAL', 'DELAYED', 'MISSING', 'UNAVAILABLE'].map((state) => <Metric key={state} label={`${LABELS[state]} 재고`} value={count(inventoryBreakdown[state])} />)}</dl></Section>
    <Section title="서울 전체 운영 분석" description="OPS-01/03과 같은 저장된 서울 전체 결과입니다. 현재 지도 범위와 구분합니다." state={global.dataState}><dl className="operations-data-metrics"><Metric label="결과 ID" value={global.resultId || '게시된 결과 없음'} /><Metric label="기준 시각" value={time(global.referenceTime)} /><Metric label="게시 시각" value={time(global.publishedAt)} /><Metric label="신선도 유효 시각" value={time(global.freshUntil)} /><Metric label="만료 시각" value={time(global.expiresAt)} /><Metric label="활성 대여소" value={count(global.activePublicStationCount)} /><Metric label="평가 완료" value={count(global.evaluatedStationCount)} /><Metric label="정상 추론" value={count(global.normalInferenceCount)} /><Metric label="재고 결측" value={count(global.inventoryMissingCount)} /><Metric label="재고 지연" value={count(global.inventoryDelayedCount)} /><Metric label="재고 사용 불가" value={count(global.inventoryUnavailableCount)} /><Metric label="추론 정보 부족" value={count(global.inferenceInsufficientCount)} /><Metric label="미평가" value={count(global.unevaluatedCount)} /><Metric label="생성 소요" value={global.generationDurationMs == null ? '확인 정보 없음' : `${global.generationDurationMs.toLocaleString('ko-KR')}ms`} /><Metric label="모델 버전" value={global.modelVersion || '확인 정보 없음'} /></dl></Section>
    <Section title="현재 지도 범위" description="OPS-02에서 마지막으로 분석한 지도 범위 한정 스냅샷이며 서울 전체 상태가 아닙니다." state={map.dataState}><dl className="operations-data-metrics"><Metric label="분석 여부" value={map.hasRecentSnapshot ? (map.snapshotExpired ? '만료됨' : '유효함') : '아직 분석한 범위 없음'} /><Metric label="기준 시각" value={time(map.referenceTime)} /><Metric label="분석 완료" value={count(map.evaluatedStationCount)} /></dl></Section>
    <div className="operations-data-supporting"><Section title="대여소 이용 패턴" description="저장된 대여소 이용 패턴 프로필의 커버리지입니다." state={profile.dataState}><dl className="operations-data-metrics"><Metric label="활성 공개" value={count(profile.activePublicStationCount)} /><Metric label="프로필 보유" value={count(profile.profileAvailableStationCount)} /><Metric label="커버리지" value={ratio(profile.coverageRatio)} /><Metric label="최신 생성" value={time(profile.latestGeneratedAt)} /></dl></Section><Section title="예측 배치 (이력 전용)" description="현재 즉시 추론 상태로 쓰지 않는 과거 배치입니다." state={result.prediction?.dataState}>{result.prediction ? <dl className="operations-data-metrics"><Metric label="게시 시각" value={time(result.prediction.publishedAt)} /><Metric label="커버리지" value={ratio(result.prediction.coverageRatio)} /></dl> : <p className="operations-data-absence">유효한 이력 배치 없음</p>}</Section></div>
    <details className="operations-data-section operations-data-export-details"><summary className="operations-data-section-heading"><div><h2>데이터 내보내기</h2><p>현재 서비스 재고를 원본 그대로 담은 CSV 또는 Parquet 파일을 생성합니다.</p></div></summary><div className="operations-data-section-body"><DataExportPanel adapter={adapter} permissions={result.permissions} /></div></details>
  </main>;
}
